using Microsoft.Dynamics365.LocalizationFramework;
using Microsoft.Dynamics365.LocalizationFramework.Format.FileGeneration;
[ExtensionOf(classstr(ERFormatMappingRunCustomCallbackProvider))]
internal final class AVADAIERFormatMappingRunCustomCallbackProvider_Cls_Extension
{
    public AVADAIERFileCallback dAIdestinationCallback;
}

Method.Source:
public boolean isProvidingCallback()
{
    var ret = next isProvidingCallback();
    return true; //Here you may enter any logic based on format mapping table record provided
}

public IDestinationFileCallback createDestinationCallback()
{
    var ret = next createDestinationCallback();
    if (ret == null)
    {
        ret = new AVADAIERFileCallback(formatMappingTable); //same here, your destination callback may be different for different formats, you may let user set it up somewhere.
        dAIdestinationCallback = ret;
    }
    return ret;
}

public void setFormatMapping(ERFormatMapping _formatMapping)
{
    next setFormatMapping(_formatMapping);

    if (dAIdestinationCallback)
    {
        dAIdestinationCallback.setFormatMapping(_formatMapping);
    }
}
